with recursive cte0 (mq_id,mq_parentId,mq_name,mq_level,mqCycleMark,path) as (select fne1_0.id,fne1_0.parent_id,fne1_0.name,0,0,cast(concat(char(0 using ascii),coalesce(concat(fne1_0.id,''),char(0 using ascii)),char(0 using ascii),char(0 using ascii)) as char(22000)) from folder_nodes fne1_0 where fne1_0.id in (?) union all select fne2_0.id,fne2_0.parent_id,fne2_0.name,(cte01_0.mq_level+cast(? as signed)),case when cte01_0.path like concat('%',replace(replace(replace(concat(char(0 using ascii),coalesce(concat(fne2_0.id,''),char(0 using ascii)),char(0 using ascii),char(0 using ascii)),'~','~~'),'?','~?'),'%','~%'),'%') escape '~' then 1 else 0 end,concat(cte01_0.path,char(0 using ascii),coalesce(concat(fne2_0.id,''),char(0 using ascii)),char(0 using ascii),char(0 using ascii)) from cte0 cte01_0,folder_nodes fne2_0 where fne2_0.parent_id=cte01_0.mq_id and cte01_0.mq_level<? and not(cte01_0.mqCycleMark)),cte1 (mq_parentId,mq_children) as (select cte02_0.mq_parentId,count(1) from cte0 cte02_0 where cte02_0.mq_level<=? and not(cte02_0.mqCycleMark) group by 1) select fne3_0.id,cte11_0.mq_children,(select min(cte03_0.mq_id) from cte0 cte03_0 where cte03_0.mq_level>?),(select min(cte04_0.mq_id) from cte0 cte04_0 where cte04_0.mqCycleMark) from folder_nodes fne3_0 left join cte1 cte11_0 on cte11_0.mq_parentId=fne3_0.id where fne3_0.id<=? order by 1
